update public.lessons
set duration_seconds = 269,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_01/lesson_01_seg_01.mp3", "lesson_01/lesson_01_seg_02.mp3"], "total_audio_seconds": 107.55, "timed_text": [{"start_s": 0.24, "text": "Welcome to Relentless."}, {"start_s": 11.44, "text": "This is mental performance training."}, {"start_s": 20.84, "text": "The framework is called MAC."}, {"start_s": 56.46, "text": "Mindfulness — notice where your attention is and choose where it goes."}, {"start_s": 64.24, "text": "Acceptance — feel uncomfortable without treating it like an emergency."}, {"start_s": 79.51, "text": "Commitment — show up, regardless of how you feel."}, {"start_s": 105.77, "text": "Which one do you need most?"}]}, {"type": "flash_cards", "ambient_audio": "ambient/ambient_music.mp3", "cards": [{"front": "M — Mindfulness", "back": "Notice where your attention goes. Choose where it goes."}, {"front": "A — Acceptance", "back": "Feel the discomfort. Don''t react to it."}, {"front": "C — Commitment", "back": "Show up. Regardless of how you feel."}]}, {"type": "voiceover", "audio_files": ["lesson_01/lesson_01_seg_03.mp3"], "total_audio_seconds": 26.0, "timed_text": [{"start_s": 0.66, "text": "Got your answer?"}, {"start_s": 2.72, "text": "Remember it."}, {"start_s": 4.22, "text": "On Day 30 — I''m going to ask you again."}, {"start_s": 7.94, "text": "Go ahead and hit the journal."}, {"start_s": 9.9, "text": "One question."}, {"start_s": 11.66, "text": "Be honest."}, {"start_s": 13.88, "text": "After you finish — you''ll officially complete Day 1."}]}, {"type": "journal_prompt", "prompt": "Which of the three — Mindfulness, Acceptance, or Commitment — is your biggest weakness right now? Why?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000001';

update public.lessons
set duration_seconds = 247,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_02/lesson_02_seg_01.mp3"], "total_audio_seconds": 114.01, "timed_text": [{"start_s": 1.07, "text": "Day 2."}, {"start_s": 5.81, "text": "Today I want to show you the exact science."}, {"start_s": 16.51, "text": "Daniel Kahneman won the Nobel Prize in 2002."}, {"start_s": 27.13, "text": "The brain runs on two systems."}, {"start_s": 28.83, "text": "System 1 is fast."}, {"start_s": 31.41, "text": "Automatic."}, {"start_s": 32.25, "text": "Instinctive."}, {"start_s": 55.27, "text": "System 2 is slow."}, {"start_s": 58.53, "text": "Deliberate."}, {"start_s": 61.49, "text": "Analytical."}, {"start_s": 82.57, "text": "Choking is what happens when System 2 tries to take control of something System 1 already owns."}, {"start_s": 90.15, "text": "The fix isn''t to think less."}, {"start_s": 93.03, "text": "It''s to train your mind to step back."}, {"start_s": 102.41, "text": "Right now I want you to find your version of that moment."}]}, {"type": "prompt_cards", "ambient_audio": "ambient/ambient_music.mp3", "cards": [{"intro_hold_seconds": 0, "prompt": "Describe a moment in competition or training where your mind worked against you. Where were you? What was happening? What did your brain start doing instead of competing? Be detailed.", "min_entry_seconds": 0}], "summary": {"display": "last", "header": "", "hold_seconds": 0}}, {"type": "multi_select", "ambient_audio": "ambient/ambient_music.mp3", "prompt": "What was your brain doing? Tap all that apply.", "options": ["Thinking about the outcome", "Watching my competition", "Tracking time, score, or distance", "Replaying a mistake mid-performance", "Thinking about how my body feels", "Worrying about what others think", "Thinking about what comes next"], "confirm_label": "Confirm", "min_select": 0}, {"type": "voiceover", "audio_files": ["lesson_02/lesson_02_seg_02.mp3"], "total_audio_seconds": 22.93, "timed_text": [{"start_s": 1.71, "text": "What you just logged — that''s your distraction profile."}, {"start_s": 10.91, "text": "Every drill from here is training you to catch that pattern before it catches you."}, {"start_s": 17.03, "text": "Go hit the journal."}, {"start_s": 18.57, "text": "One question."}, {"start_s": 20.21, "text": "After you finish — Day 2 is complete."}]}, {"type": "journal_prompt", "prompt": "Looking at what you selected — which distraction shows up most consistently for you? Does it get worse at specific moments in competition?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000002';

update public.lessons
set duration_seconds = 149,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_03/lesson_03_seg_01.mp3"], "total_audio_seconds": 48.66, "timed_text": [{"start_s": 1.26, "text": "Day 3."}, {"start_s": 2.94, "text": "Before we go any further — we need a starting point."}, {"start_s": 6.44, "text": "Think of this like measuring your vertical before a training block."}, {"start_s": 20.26, "text": "One for each pillar — Mindfulness, Acceptance, Commitment."}, {"start_s": 24.92, "text": "Score yourself honestly from 1 to 10."}, {"start_s": 28.86, "text": "1 means it''s a major problem."}, {"start_s": 32.22, "text": "10 means you''ve got it locked in."}, {"start_s": 43.08, "text": "You''ll have 30 seconds per question."}, {"start_s": 46.04, "text": "Read it, sit with it, and be honest."}]}, {"type": "timed_exercise", "duration_seconds": 90, "steps": [{"text": "Mindfulness — During competition, how often does your mind drift to outcomes, mistakes, or what people think — instead of staying on the task in front of you? 1 = constantly, 10 = never.", "duration_seconds": 30}, {"text": "Acceptance — How much do nerves, fear, or self-doubt affect your performance — even when you know physically you''re ready? 1 = they control me, 10 = I use them.", "duration_seconds": 30}, {"text": "Commitment — How consistent are your mental habits right now — visualization, reflection, intentional prep? 1 = nonexistent, 10 = locked in daily.", "duration_seconds": 30}]}, {"type": "voiceover", "audio_files": ["lesson_03/lesson_03_seg_02.mp3"], "total_audio_seconds": 25.02, "timed_text": [{"start_s": 1.22, "text": "Those three numbers are your baseline."}, {"start_s": 6.78, "text": "On Day 30, you''re going to answer those exact same questions again."}, {"start_s": 16.68, "text": "Hit the journal."}, {"start_s": 17.88, "text": "Write your scores down and add one sentence explaining each one."}, {"start_s": 22.32, "text": "After you finish — Day 3 is complete."}]}, {"type": "journal_prompt", "prompt": "Write your three baseline scores — M, A, C — and one sentence explaining each one."}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000003';

update public.lessons
set duration_seconds = 202,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_04/lesson_04_seg_01.mp3"], "total_audio_seconds": 80.64, "timed_text": [{"start_s": 1.04, "text": "Day 4."}, {"start_s": 2.44, "text": "You''ve got your baseline."}, {"start_s": 3.98, "text": "You know where you''re starting."}, {"start_s": 9.42, "text": "Who are you as a competitor?"}, {"start_s": 13.28, "text": "Not what you want to achieve."}, {"start_s": 15.22, "text": "Not what your stats say."}, {"start_s": 29.62, "text": "Athletes who compete from identity outperform athletes who compete from outcome."}, {"start_s": 37.0, "text": "The difference between ''I want to win'' and ''I am the kind of athlete who doesn''t quit.''"}, {"start_s": 51.32, "text": "Today you''re going to write your identity."}, {"start_s": 54.86, "text": "Present tense."}, {"start_s": 56.76, "text": "Specific."}, {"start_s": 58.14, "text": "Behavioral."}, {"start_s": 70.18, "text": "On your screen you''re going to see a few examples."}, {"start_s": 75.48, "text": "Then write two or three of your own."}]}, {"type": "examples_with_entry", "ambient_audio": "ambient/ambient_music.mp3", "examples_header": "", "examples": ["I am an athlete who shows up the same — whether I''m winning or losing.", "I am an athlete who competes through discomfort.", "I am an athlete who focuses on the next play, not the last one."], "input_prompt": "Now write 2–3 of your own. Present tense. Be specific.", "submit_label": "Save"}, {"type": "voiceover", "audio_files": ["lesson_04/lesson_04_seg_02.mp3"], "total_audio_seconds": 16.47, "timed_text": [{"start_s": 0.69, "text": "Read what you just wrote."}, {"start_s": 2.81, "text": "That''s not a goal."}, {"start_s": 4.29, "text": "That''s a decision."}, {"start_s": 5.89, "text": "Every time you open this app from here on — that''s who''s showing up."}, {"start_s": 11.35, "text": "Go hit the journal."}, {"start_s": 12.09, "text": "One question."}]}, {"type": "journal_prompt", "prompt": "Which identity statement felt most powerful? Which one felt hardest to believe?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000004';

update public.lessons
set duration_seconds = 232,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_05/lesson_05_seg_01.mp3"], "total_audio_seconds": 76.74, "timed_text": [{"start_s": 1.1, "text": "Day 5."}, {"start_s": 2.68, "text": "First physical tool."}, {"start_s": 5.22, "text": "It''s called box breathing."}, {"start_s": 7.74, "text": "Four sides."}, {"start_s": 8.8, "text": "Four seconds each."}, {"start_s": 19.12, "text": "When you''re in a high-pressure moment, your body runs hot."}, {"start_s": 25.72, "text": "Your brain shifts into threat mode."}, {"start_s": 30.3, "text": "None of that is useful for execution."}, {"start_s": 33.32, "text": "Box breathing is a reset switch."}, {"start_s": 36.34, "text": "When you control the breath, you directly activate the part of your nervous system that says calm down."}, {"start_s": 54.8, "text": "On your screen you''re going to see a circle."}, {"start_s": 68.54, "text": "Follow it."}, {"start_s": 71.46, "text": "If your mind drifts — bring it back."}, {"start_s": 74.48, "text": "That is not failure."}, {"start_s": 76.0, "text": "That is the drill."}]}, {"type": "timed_exercise", "duration_seconds": 80, "ambient_audio": "ambient/ambient_music.mp3", "interactive_model": "box_breathing", "rep_count": 5, "phase_labels": {"inhale": "Inhale through your nose. 4 seconds.", "hold_in": "Hold. 4 seconds.", "exhale": "Exhale through your mouth. 4 seconds.", "hold_out": "Hold. 4 seconds."}, "mid_overlay": {"after_rep": 3, "text": "Mind drifted? Good. Bring it back.", "duration_seconds": 5}, "visual_cues": ["Follow the circle. In through your nose.", "Stay with the rhythm. Don''t rush.", "Nice and steady. Four seconds each.", "Let everything else go.", "Mind drifted? Good. Bring it back.", "You''re building a skill. Stay present.", "Last two reps. Stay locked in.", "Almost there. Finish strong."], "steps": [{"text": "Inhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}, {"text": "Exhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}]}, {"type": "voiceover", "audio_files": ["lesson_05/lesson_05_seg_02.mp3"], "total_audio_seconds": 14.82, "timed_text": [{"start_s": 0.4, "text": "That''s box breathing."}, {"start_s": 1.6, "text": "Do that before your next practice."}, {"start_s": 4.08, "text": "Before your next competition."}, {"start_s": 7.86, "text": "The reps compound."}, {"start_s": 10.04, "text": "Go hit the journal."}]}, {"type": "journal_prompt", "prompt": "Where did your mind go during the breathing? What thought kept pulling you away from the breath?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000005';

update public.lessons
set duration_seconds = 405,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_01.mp3"], "total_audio_seconds": 58.76, "timed_text": [{"start_s": 1.32, "text": "Day 6."}, {"start_s": 6.58, "text": "Anxiety shows up in your body before it shows up in your thoughts."}, {"start_s": 9.72, "text": "Tight jaw."}, {"start_s": 11.7, "text": "Raised shoulders."}, {"start_s": 12.48, "text": "Clenched fists."}, {"start_s": 13.96, "text": "Shallow breathing."}, {"start_s": 16.16, "text": "You''ve felt all of it before a big competition."}, {"start_s": 21.96, "text": "Today we fix that."}, {"start_s": 23.88, "text": "We''re going to scan your body from head to toe."}, {"start_s": 35.22, "text": "This teaches you to read your own nervous system in real time."}, {"start_s": 48.46, "text": "Before we start — take one box breath with me."}]}, {"type": "timed_exercise", "duration_seconds": 16, "interactive_model": "box_breathing", "visual_cues": ["One full breath. Settle in.", "Follow the circle."], "steps": [{"text": "Inhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}, {"text": "Exhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}]}, {"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_02.mp3"], "total_audio_seconds": 246.32, "timed_text": [{"start_s": 0.46, "text": "Okay, so now that you''re in a good relaxed position, let''s close your eyes."}, {"start_s": 6.02, "text": "So we''re moving from the top of your head down to your feet."}, {"start_s": 10.38, "text": "At each zone, we''re going to breathe in and release whatever you find on the exhale."}, {"start_s": 17.62, "text": "Don''t force anything, just notice and let go."}, {"start_s": 22.74, "text": "So right now, focus on the top of your head."}, {"start_s": 28.31, "text": "Keep that deep breathing going as you think about the sensations on your head."}, {"start_s": 33.91, "text": "Are you leaning against the chair?"}, {"start_s": 35.43, "text": "Are you laying down?"}, {"start_s": 39.59, "text": "Give yourself nothing but pure focus and attention around your head, around your hair,"}, {"start_s": 48.03, "text": "your forehead, around your eyes."}, {"start_s": 50.71, "text": "Do you notice any tension?"}, {"start_s": 54.79, "text": "As you focus on your head and only your head, take a deep breath in and just release."}, {"start_s": 66.18, "text": "Focus on your jaw, your neck, your throat, athletes carry a lot of tension here."}, {"start_s": 74.3, "text": "I need you to breathe in, slowly exhale and simply release, relax and let go."}, {"start_s": 86.8, "text": "Take your attention to your shoulders, your upper back."}, {"start_s": 91.8, "text": "Are they raised?"}, {"start_s": 92.8, "text": "Are they tense?"}, {"start_s": 95.32, "text": "Drop them and completely relax."}, {"start_s": 98.6, "text": "One slow breath in and slowly release."}, {"start_s": 105.94, "text": "Take your attention to your chest, your lungs, breathe all the way in, release, relax and"}, {"start_s": 119.5, "text": "let go."}, {"start_s": 123.34, "text": "Take your attention to your arms."}, {"start_s": 127.25, "text": "Focus on the nerves, going all the way down to your hands, your fingers."}, {"start_s": 132.57, "text": "Let your hands completely relax, unclench your fists and just completely rest heavy."}, {"start_s": 140.61, "text": "Keep working on that breath, release, relax and let go."}, {"start_s": 147.95, "text": "Take your attention to your core, your stomach."}, {"start_s": 152.43, "text": "This is where nerves live."}, {"start_s": 155.19, "text": "Just breathe into that core, breathe into that stomach."}, {"start_s": 159.31, "text": "Let it expand, then release, relax and let go."}, {"start_s": 168.28, "text": "Focus on your hips, your legs, your feet."}, {"start_s": 175.14, "text": "Every sensation you feel, everything is right where it needs to be."}, {"start_s": 180.1, "text": "Your total undivided attention, simply focusing on your lower extremities, all the way to the"}, {"start_s": 188.5, "text": "floor or wherever you are, laying down in a comfortable place."}, {"start_s": 192.82, "text": "Just feel the ground underneath you."}, {"start_s": 196.54, "text": "Keep working that breath and just release, relax and let go."}, {"start_s": 204.6, "text": "Now just zoom out for a second and see your whole body for what it is."}, {"start_s": 209.76, "text": "Your fully present where you are, you''re in one place, one time, one moment."}, {"start_s": 217.2, "text": "Take that full breath in, breathe in that good energy, that peace and with the breath"}, {"start_s": 227.02, "text": "as we release, we''re letting go of all tension, all stressors, release out on your exhale and"}, {"start_s": 237.84, "text": "just feel the peace take over."}, {"start_s": 242.48, "text": "Again, release, relax and let go."}]}, {"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_03.mp3"], "total_audio_seconds": 24.32, "timed_text": [{"start_s": 0.66, "text": "Open your eyes."}, {"start_s": 3.02, "text": "You just learned how to read your nervous system and reset it in under two minutes."}, {"start_s": 14.26, "text": "Aware athletes don''t get blindsided by their own bodies."}, {"start_s": 20.44, "text": "Go hit the journal."}]}, {"type": "journal_prompt", "prompt": "Where did your body hold the most tension? Does that same spot show up when you compete?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000006';

update public.lessons
set duration_seconds = 214,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_07/lesson_07_seg_01.mp3"], "total_audio_seconds": 69.88, "timed_text": [{"start_s": 0.5, "text": "Day 7."}, {"start_s": 2.1, "text": "You''ve done your first week."}, {"start_s": 4.44, "text": "Breathing."}, {"start_s": 5.58, "text": "Body scan."}, {"start_s": 6.78, "text": "Awareness."}, {"start_s": 9.78, "text": "Today we build the tool that ties all of it together."}, {"start_s": 13.0, "text": "It''s called a focus anchor."}, {"start_s": 18.88, "text": "A word, a short phrase, or a physical sensation that your mind comes back to when it starts to drift."}, {"start_s": 31.76, "text": "Today you choose yours on purpose."}, {"start_s": 37.74, "text": "It should be short — one or two words max."}, {"start_s": 41.94, "text": "Process-focused, not outcome-focused."}, {"start_s": 50.76, "text": "Examples: next play, breathe, process, here, trust."}, {"start_s": 59.0, "text": "Before we start — take one box breath to settle in."}]}, {"type": "timed_exercise", "duration_seconds": 16, "interactive_model": "box_breathing", "visual_cues": ["One box breath. Settle in.", "Follow the circle."], "steps": [{"text": "Inhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}, {"text": "Exhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}]}, {"type": "anchor_entry", "ambient_audio": "ambient/ambient_music.mp3", "entry_prompt": "What is your focus anchor? One or two words. Choose something that brings you into the present moment.", "save_label": "Save", "hold_prompt": "Hold your anchor. When your mind drifts — and it will — bring it back. That''s the rep.", "continue_label": "Continue"}, {"type": "voiceover", "audio_files": ["lesson_07/lesson_07_seg_02.mp3"], "total_audio_seconds": 23.3, "timed_text": [{"start_s": 1.78, "text": "That word you just saved — that''s your reset tool."}, {"start_s": 5.1, "text": "In competition, when things get loud in your head, that''s what you come back to."}, {"start_s": 13.88, "text": "We''re going to use it throughout the rest of this program."}, {"start_s": 16.82, "text": "Go hit the journal."}, {"start_s": 21.18, "text": "That''s your first week of Relentless."}]}, {"type": "journal_prompt", "prompt": "What anchor did you choose and why? When in competition do you think you''ll need it most?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000007';

